using System.Text; using Microsoft.AspNetCore.Authentication.JwtBearer; using Microsoft.EntityFrameworkCore; using Microsoft.IdentityModel.Tokens;
var builder=WebApplication.CreateBuilder(args);builder.Services.AddControllers();builder.Services.AddEndpointsApiExplorer();builder.Services.AddSwaggerGen();builder.Services.AddHttpClient();builder.Services.AddScoped<AuthService>();builder.Services.AddScoped<IPaymentService,PaytmPaymentService>();builder.Services.AddScoped<INotificationService,NotificationService>();builder.Services.AddDbContext<EComDbContext>(o=>o.UseNpgsql(builder.Configuration.GetConnectionString("DefaultConnection")));var jwtKey=builder.Configuration["Jwt:Key"]??throw new InvalidOperationException("Jwt:Key is required.");builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme).AddJwtBearer(o=>o.TokenValidationParameters=new TokenValidationParameters{ValidateIssuerSigningKey=true,IssuerSigningKey=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(jwtKey)),ValidateIssuer=true,ValidIssuer=builder.Configuration["Jwt:Issuer"],ValidateAudience=true,ValidAudience=builder.Configuration["Jwt:Audience"],ValidateLifetime=true,ClockSkew=TimeSpan.FromMinutes(1)});builder.Services.AddAuthorization();builder.Services.AddCors(o=>o.AddPolicy("Frontend",p=>p.AllowAnyOrigin().AllowAnyHeader().AllowAnyMethod()));var app=builder.Build();using(var scope=app.Services.CreateScope())await SeedData.InitializeAsync(scope.ServiceProvider.GetRequiredService<EComDbContext>(),scope.ServiceProvider.GetRequiredService<AuthService>(),scope.ServiceProvider.GetRequiredService<IConfiguration>());if(app.Environment.IsDevelopment()){app.UseSwagger();app.UseSwaggerUI();}app.UseHttpsRedirection();app.UseCors("Frontend");app.UseAuthentication();app.UseAuthorization();app.MapControllers();app.MapGet("/api/health",()=>Results.Ok(new{status="ok",service="ecom-api",timestamp=DateTimeOffset.UtcNow}));app.Run();
